mapper.update:
update delivery_order
deliveryman_id = #{deliverymanId}, status = #{status}, accept_time = #{acceptTime}, pickup_time = #{pickupTime}, delivered_time = #{deliveredTime}, update_time = now()
where id = #{id}

mapper.select:
select d.*, o.number as order_number, o.delivery_fee as delivery_fee, m.shop_name as shop_name, m.phone as merchant_phone, m.address as pickup_address, o.address as receiver_address, o.consignee as consignee, o.phone as phone from delivery_order d left join orders o on o.id = d.order_id left join merchant m on m.id = d.merchant_id
d.deliveryman_id = #{deliverymanId}
and d.status = #{dto.status}
order by d.accept_time desc, d.id desc
